#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void mean_reduce_kernel(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t reduce_dim_size,
    int64_t outer_elements,
    int64_t inner_elements
) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) return;

    // Calculate which element we're processing
    int64_t outer_idx = idx / (reduce_dim_size * inner_elements);
    int64_t remaining = idx % (reduce_dim_size * inner_elements);
    int64_t reduce_idx = remaining / inner_elements;
    int64_t inner_idx = remaining % inner_elements;

    // Compute the output index
    int64_t output_idx = outer_idx * inner_elements + inner_idx;

    // Accumulate values for the mean
    half sum = __hzero();
    for (int64_t i = 0; i < reduce_dim_size; ++i) {
        int64_t input_idx = outer_idx * (reduce_dim_size * inner_elements) + i * inner_elements + inner_idx;
        sum = __hadd(sum, input[input_idx]);
    }

    // Compute mean
    half mean_val = __hdiv(sum, __float2half((float)reduce_dim_size));
    output[output_idx] = mean_val;
}

// Host wrapper function
extern "C" void launch_mean_reduce(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t reduce_dim_size,
    int64_t outer_elements,
    int64_t inner_elements
) {
    const int block_size = 256;
    const int grid_size = (total_elements + block_size - 1) / block_size;

    mean_reduce_kernel<<<grid_size, block_size>>>(
        input, output, total_elements, reduce_dim_size, outer_elements, inner_elements
    );

    cudaDeviceSynchronize();
}
"""

